{
  "name": "@nice4work/open-queue",
  "version": "2.0.0",
  "description": "Task orchestration layer for OpenCode - checklist task queues with loop guard on top of native delivery",
  "keywords": [
    "opencode",
    "plugin",
    "queue",
    "checklist",
    "task-orchestration"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "open-queue": "bin/install.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "dist",
    "bin",
    "README.md"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "clean": "rm -rf dist",
    "test": "npm run build && node --test test/queue.test.mjs"
  },
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.0"
  },
  "devDependencies": {
    "@opencode/client": "2.0.32",
    "@opencode/plugin": "2.0.32",
    "@types/node": "^20.14.10",
    "typescript": "^5.9.3"
  }
}
